 if(stage>4)return null;
 async function submit(e){e.preventDefault();setSaving(true);const ok=await onSave({action:'qualifyClient',stage,qualificationStatus:value});setSaving(false);setMessage(ok?'Qualificação registrada no histórico.':'Não foi possível salvar a qualificação.')}
